export function clamp(x: number, lo: number, hi: number, wrap = false): number {
  if (wrap) {
    const span = hi - lo;
    return span === 0 ? lo : ((((x - lo) % span) + span) % span) + lo;
  }

  return Math.min(hi, Math.max(lo, x));
}

export function clamp(x: number, lo: number, hi: number): string {
  return String(Math.min(hi, Math.max(lo, x)));
}

export function bound(x: number, lo: number, hi: number): number {
  return Math.min(hi, Math.max(lo, x));
}
